import * as THREE from 'three/webgpu';
import { uv, float, vec3, vec4, mix, smoothstep, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'data-ticker-ribbon';
  group.position.set(0, 0, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const RAIL_W = 7.0;
  const RAIL_H = 0.35;

  // --- Rail plane ---
  const railGeo = new THREE.PlaneGeometry(RAIL_W, RAIL_H);
  const railMat = new THREE.MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    color: new THREE.Color('#111117'),
  });

  // Edge fade using TSL node on opacity, mapped to world-ish uv.x
  const fadeStart = float(0.09);
  const fadeEnd = float(0.91);
  const u = uv().x;
  const leftFade = smoothstep(float(0.0), fadeStart, u);
  const rightFade = float(1.0).sub(smoothstep(fadeEnd, float(1.0), u));
  const fadeAlpha = leftFade.mul(rightFade);
  railMat.colorNode = vec4(vec3(0.067, 0.067, 0.09), 1.0);
  railMat.opacityNode = fadeAlpha;
  railMat.transparent = true;

  const rail = new THREE.Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  group.add(rail);

  // hairlines top/bottom
  const hairlineMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#23232b'),
    roughness: 0.6,
    metalness: 0.2,
  });
  const hairlineGeo = new THREE.PlaneGeometry(RAIL_W, 0.006);
  const topHairline = new THREE.Mesh(hairlineGeo, hairlineMat);
  topHairline.position.set(0, RAIL_H / 2, 0.001);
  group.add(topHairline);
  const bottomHairline = new THREE.Mesh(hairlineGeo, hairlineMat);
  bottomHairline.position.set(0, -RAIL_H / 2, 0.001);
  group.add(bottomHairline);

  // --- Content strip ---
  const entries = [
    'CAL NA-01 BEAT 28800 VPH',
    'POWER RESERVE 72H',
    'CASE 40.5 MM 904L',
    'REF 5811 IN STOCK',
    'WAITLIST 1204',
    'NEXT FITTING JUL 18',
  ];

  const tickMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#ff2a38'),
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.5,
    roughness: 0.5,
    metalness: 0.2,
  });
  const tickGeo = new THREE.PlaneGeometry(0.02, 0.14);

  const textMeshes = [];
  const gap = 0.5; // 2x base unit

  function buildStrip() {
    const stripGroup = new THREE.Group();
    let cursorX = 0;
    entries.forEach((str) => {
      const textMesh = ctx.fontAtlas.createText(str, {
        font: 'JetBrains Mono',
        fontSize: 13,
        fontWeight: 700,
        letterSpacing: 0.06,
        lineHeight: 1,
        color: '#e8ecf2',
      });
      textMesh.position.set(cursorX, 0, 0.02);
      stripGroup.add(textMesh);
      textMeshes.push(textMesh);

      const bbox = new THREE.Box3().setFromObject(textMesh);
      const width = bbox.max.x - bbox.min.x || str.length * 0.09;
      cursorX += width + gap;

      const tick = new THREE.Mesh(tickGeo, tickMat);
      tick.position.set(cursorX, 0, 0.02);
      stripGroup.add(tick);
      cursorX += gap;
    });
    stripGroup.userData.stripWidth = cursorX;
    return stripGroup;
  }

  const stripA = buildStrip();
  const stripWidth = stripA.userData.stripWidth;
  const stripB = buildStrip();
  stripB.position.x = stripWidth;

  const contentGroup = new THREE.Group();
  contentGroup.add(stripA, stripB);
  contentGroup.position.x = -stripWidth / 2;
  group.add(contentGroup);

  // --- Apply fly-through primitive for constant leftward velocity ---
  const speed = 0.4;
  ctx.primitives['fly-through'](contentGroup, {
    depthUnits: 0,
    speed,
    axis: 'x',
    direction: -1,
    loopLength: stripWidth,
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    railGeo.dispose();
    railMat.dispose();
    hairlineGeo.dispose();
    hairlineMat.dispose();
    tickGeo.dispose();
    tickMat.dispose();
    textMeshes.forEach((m) => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
    if (contentGroup.userData.timeline) {
      contentGroup.userData.timeline.kill();
    }
    if (contentGroup.userData.cleanup) {
      contentGroup.userData.cleanup();
    }
  };

  return group;
}
